## 4. VFX IMPLEMENTATION — PRIORITY LOGIC

### Camera Shake System
```typescript
interface CameraShakeData {
  intensity: number;      // Current shake magnitude (0-1)
  decayRate: number;      // Decay per frame (e.g., 0.92)
  duration: number;       // Frames until fully decayed
  offsetX: number;        // X offset position
  offsetY: number;        // Y offset position
}

class CameraShakeSystem {
  private shakeQueue: CameraShakeData[] = [];

  triggerImpact(impactVelocity: number, impactType: 'bullet' | 'explosion' | 'death') {
    const baseIntensity = impactType === 'bullet' ? 0.15 : 
                          impactType === 'explosion' ? 0.3 : 0.8;
    const decayRate = 0.92;
    const duration = Math.ceil(Math.log2(baseIntensity / 0.01) * 60); // ~60fps decay

    this.shakeQueue.push({
      intensity: baseIntensity,
      decayRate,
      duration,
      offsetX: (Math.random() - 0.5) * baseIntensity * 2,
      offsetY: (Math.random() - 0.5) * baseIntensity * 2
    });
  }

  applyShake(): Vector2 {
    let totalOffset = new Vector2(0, 0);

    for (const shake of this.shakeQueue) {
      if (shake.duration <= 0) {
        this.shakeQueue = this.shakeQueue.filter(s => s !== shake);
        continue;
      }

      shake.duration--;
      shake.intensity *= shake.decayRate;

      totalOffset.x += shake.offsetX * shake.intensity;
      totalOffset.y += shake.offsetY * shake.intensity;
    }

    return totalOffset;
  }
}
```

### Hit-Stop Manager
```typescript
class HitStopManager {
  private isFrozen: boolean = false;
  private freezeDuration: number = 0;
  private lastFrameTime: number = 0;

  triggerImpact(impactSeverity: 'heavy' | 'medium' | 'light') {
    const durationMap = {
      heavy: 120,   // 120ms at 60fps
      medium: 40,   // 40ms at 60fps
      light: 15     // 15ms at 60fps
    };

    this.freezeDuration = durationMap[impactSeverity];
    this.isFrozen = true;
  }

  shouldProcessFrame(currentTime: number): boolean {
    if (!this.isFrozen) return true;

    const elapsed = currentTime - this.lastFrameTime;
    if (elapsed >= this.freezeDuration / 1000) { // Convert to seconds
      this.isFrozen = false;
      this.freezeDuration = 0;
      return true;
    }

    return false;
  }
}
```

### Particle Manager (Centralized Pool with 500 Cap)
```typescript
class ParticleManager {
  private pool: Particle[] = [];
  private activeParticles: Particle[] = [];
  private maxParticles: number = 500;

  constructor() {
    // Pre-allocate particle pool
    for (let i = 0; i < this.maxParticles; i++) {
      this.pool.push(new Particle());
    }
  }

  spawnExplosion(position: Vector3, color: Color, count: number) {
    const particlesToSpawn = Math.min(count, this.maxParticles - this.activeParticles.length);

    for (let i = 0; i < particlesToSpawn; i++) {
      const particle = this.pool.pop();
      if (!particle) continue;

      particle.position.copy(position);
      particle.velocity.set(
        (Math.random() - 0.5) * 150,
        (Math.random() - 0.5) * 150,
        (Math.random() - 0.5) * 100
      );
      particle.life = 1.5; // seconds
      particle.color.copy(color);
      particle.size = 2 + Math.random() * 4;

      this.activeParticles.push(particle);
    }
  }

  update(deltaTime: number) {
    for (let i = this.activeParticles.length - 1; i >= 0; i--) {
      const particle = this.activeParticles[i];
      particle.life -= deltaTime;

      if (particle.life <= 0) {
        this.pool.push(particle);
        this.activeParticles.splice(i, 1);
      }
    }

    // Enforce hard cap
    while (this.activeParticles.length > this.maxParticles) {
      const oldest = this.activeParticles.shift();
      if (oldest) this.pool.push(oldest);
    }
  }

  dispose() {
    for (const particle of this.pool) {
      particle.geometry?.dispose();
      particle.material?.dispose();
    }
    this.pool = [];
    this.activeParticles = [];
  }
}
```

### Shockwave Ring System
```typescript
class ShockwaveRing {
  private ring: THREE.Mesh;
  private meshMaterial: THREE.MeshBasicMaterial;

  constructor() {
    const geometry = new THREE.RingGeometry(1, 1.2, 32);
    const material = new THREE.MeshBasicMaterial({
      color: 0x00ffff,
      transparent: true,
      opacity: 1,
      side: THREE.DoubleSide
    });

    this.ring = new THREE.Mesh(geometry, material);
    this.ring.position.y = 0.1;
    this.ring.rotation.x = -Math.PI / 2;

    // Dispose materials on cleanup
    this.ring.geometry.dispose({
      type: 'BufferGeometry',
      attribute: { value: null },
      index: { value: null }
    });
    this.ring.material?.dispose();
  }

  activate(position: Vector3) {
    this.ring.position.copy(position);
    this.ring.scale.set(1, 1, 1);
    this.ring.material.opacity = 1;

    // Animate in update loop
    this.ring.userData.scaleSpeed = 0.15;
    this.ring.userData.opacityDecay = 0.03;
  }

  update(deltaTime: number) {
    const scale = this.ring.scale.x;
    this.ring.scale.set(scale + this.ring.userData.scaleSpeed, 
                       this.ring.scale.y + this.ring.userData.scaleSpeed,
                       this.ring.scale.z + this.ring.userData.scaleSpeed);
    this.ring.material.opacity -= this.ring.userData.opacityDecay;

    if (this.ring.material.opacity <= 0) {
      return false; // Should be removed
    }

    return true;
  }
}
```

### Floating Text System
```typescript
class FloatingTextManager {
  private textPool: Array<{ mesh: THREE.Mesh, life: number }> = [];
  private maxTexts: number = 20;

  spawnScore(position: Vector3, text: string) {
    const geometry = new THREE.TextGeometry(text, {
      font: this.generateFont(),
      size: 1.5,
      height: 0.2,
      curveSegments: 4,
      bevelEnabled: false
    });

    const material = new THREE.MeshBasicMaterial({
      color: 0xffff00,
      transparent: true,
      opacity: 1
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.copy(position);
    mesh.position.y += 2;
    mesh.lookAt(camera.position);

    // Dispose on cleanup
    geometry.dispose();
    material?.dispose();

    this.textPool.push({ mesh, life: 3 });
  }

  update(deltaTime: number) {
    for (let i = this.textPool.length - 1; i >= 0; i--) {
      const entry = this.textPool[i];
      entry.life -= deltaTime;

      if (entry.life <= 0) {
        entry.mesh.geometry?.dispose();
        entry.mesh.material?.dispose();
        this.textPool.splice(i, 1);
      } else {
        entry.mesh.position.y += 0.05 * deltaTime;
        entry.mesh.scale.multiplyScalar(1.02); // Scale up over time
      }
    }
  }

  private generateFont(): THREE.Font {
    // Generate font via Canvas API to avoid external font files
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 512;
    const ctx = canvas.getContext('2d');

    if (!ctx) return null;

    // Draw pixel art-style font for 'A'
    ctx.fillStyle = '#000';
    ctx.font = 'bold 400px monospace';
    ctx.fillText('A', 100, 400);

    const imageData = ctx.getImageData(0, 0, 512, 512);
    const data = imageData.data;

    // Convert to Three.js font structure (simplified)
    return this.convertCanvasToFont(imageData);
  }

  private convertCanvasToFont(imageData: ImageData): THREE.Font {
    // Simplified conversion - in production would use full font parsing
    const font = new THREE.Font();
    font.type = 'pixel';
    return font;
  }
}
```

---

## 5. FILE ARCHITECTURE — COMPLETE ES MODULE STRUCTURE

### Root Level Files
```
[GameName]/
├── index.html                          # Entry point with Glassmorphism UI overlay
├── main.js                             # Game bootstrapper, scene setup, composer initialization
└── src/
    ├── game/
    │   ├── Game.ts                     # Core game loop, state management, win/loss conditions
    │   ├── Player.ts                   # Player entity with health, movement, shooting
    │   ├── InputManager.ts             # Unified Dual-Input (Keyboard + Gamepad API)
    │   └── Level.ts                    # Enemy grid generation and wave progression
    ├── entities/
    │   ├── Projectile.ts               # Pool-managed projectiles (player/enemy bullets)
    │   ├── Enemy.ts                    # Pool-managed enemies with AI behavior
    │   ├── Particle.ts                 # Pool-managed particle system
    │   └── Shockwave.ts                # Emissive ring effects on impacts
    ├── vfx/
    │   ├── CameraShakeSystem.ts        # Trauma-based decaying shake
    │   ├── HitStopManager.ts           # Timescale dilation on impacts
    │   ├── ParticleManager.ts          # Centralized particle pool (500 cap)
    │   ├── MotionTrails.ts             # Fast-moving object trails
    │   └── FloatingText.ts             # Dynamic score text (3D/HTML hybrid)
    ├── materials/
    │   └── NeonMaterial.ts             # Reusable PBR neon emissive material
    └── utils/
        ├── NoiseUtils.ts               # Simplex noise for procedural displacement
        └── MathUtils.ts                # Vector math, collision detection
└── shared/
    ├── vfx/
    │   ├── EffectComposerSetup.ts      # Bloom pass configuration (tuned neon)
    │   └── PostProcessingConfig.ts     # Shared post-processing settings
    └── audio/
        └── AudioSynth.ts               # Web Audio API synthesizer for SFX/music
```

