// Enemy emissive texture generation
function generateEnemyEmissiveTexture(type: 'small' | 'large'): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = 64;
  canvas.height = 64;
  const ctx = canvas.getContext('2d');

  // Base color fill
  const baseColor = type === 'small' ? '#00ff88' : '#aa00ff';
  ctx.fillStyle = baseColor;
  ctx.fillRect(0, 0, 64, 64);

  // Noise displacement using Simplex noise
  const noise = createSimplexNoise();
  for (let i = 0; i < 100; i++) {
    const x = Math.random() * 64;
    const y = Math.random() * 64;
    const intensity = noise([x, y]) * 20;

    ctx.fillStyle = type === 'small' 
      ? `rgba(0, 255, 136, ${Math.abs(intensity) / 100})`
      : `rgba(170, 0, 255, ${Math.abs(intensity) / 100})`;
    ctx.fillRect(x, y, 4, 4);
  }

  return canvas;
}

// Particle texture generation
function generateParticleTexture(type: 'spark' | 'debris'): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = 32;
  canvas.height = 32;
  const ctx = canvas.getContext('2d');

  if (type === 'spark') {
    // Jagged triangle spark
    ctx.beginPath();
    ctx.moveTo(16, 0);
    ctx.lineTo(32, 16);
    ctx.lineTo(16, 32);
    ctx.lineTo(0, 16);
    ctx.closePath();

    const gradient = ctx.createLinearGradient(16, 0, 16, 32);
    gradient.addColorStop(0, 'rgba(255, 255, 255, 1)');
    gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = gradient;
    ctx.fill();
  } else {
    // Irregular debris polygon
    const points = [];
    for (let i = 0; i < 6; i++) {
      const angle = (i / 6) * Math.PI * 2 + Math.random() * 0.5 - 0.25;
      const radius = 10 + Math.random() * 8;
      points.push({
        x: 16 + Math.cos(angle) * radius,
        y: 16 + Math.sin(angle) * radius
      });
    }

    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);
    for (let i = 1; i < points.length; i++) {
      ctx.lineTo(points[i].x, points[i].y);
    }
    ctx.closePath();

    ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
    ctx.fill();
  }

  return canvas;
}
