### Camera Shake System
```typescript
interface CameraShakeData {
  intensity: number;      // Current shake magnitude (0-1)
  decayRate: number;      // Decay per frame (e.g., 0.92)
  duration: number;       // Frames until fully decayed
  offsetX: number;        // X offset position
  offsetY: number;        // Y offset position
}

class CameraShakeSystem {
  private shakeQueue: CameraShakeData[] = [];

  triggerImpact(impactVelocity: number, impactType: 'bullet' | 'explosion' | 'death') {
    const baseIntensity = impactType === 'bullet' ? 0.15 : 
                          impactType === 'explosion' ? 0.3 : 0.8;
    const decayRate = 0.92;
    const duration = Math.ceil(Math.log2(baseIntensity / 0.01) * 60); // ~60fps decay

    this.shakeQueue.push({
      intensity: baseIntensity,
      decayRate,
      duration,
      offsetX: (Math.random() - 0.5) * baseIntensity * 2,
      offsetY: (Math.random() - 0.5) * baseIntensity * 2
    });
  }

  applyShake(): Vector2 {
    let totalOffset = new Vector2(0, 0);

    for (const shake of this.shakeQueue) {
      if (shake.duration <= 0) {
        this.shakeQueue = this.shakeQueue.filter(s => s !== shake);
        continue;
      }

      shake.duration--;
      shake.intensity *= shake.decayRate;

      totalOffset.x += shake.offsetX * shake.intensity;
      totalOffset.y += shake.offsetY * shake.intensity;
    }

    return totalOffset;
  }
}
