class HitStopManager {
  private isFrozen: boolean = false;
  private freezeDuration: number = 0;
  private lastFrameTime: number = 0;

  triggerImpact(impactSeverity: 'heavy' | 'medium' | 'light') {
    const durationMap = {
      heavy: 120,   // 120ms at 60fps
      medium: 40,   // 40ms at 60fps
      light: 15     // 15ms at 60fps
    };

    this.freezeDuration = durationMap[impactSeverity];
    this.isFrozen = true;
  }

  shouldProcessFrame(currentTime: number): boolean {
    if (!this.isFrozen) return true;

    const elapsed = currentTime - this.lastFrameTime;
    if (elapsed >= this.freezeDuration / 1000) { // Convert to seconds
      this.isFrozen = false;
      this.freezeDuration = 0;
      return true;
    }

    return false;
  }
}
