### Particle Manager (Centralized Pool with 500 Cap)
```typescript
class ParticleManager {
  private pool: Particle[] = [];
  private activeParticles: Particle[] = [];
  private maxParticles: number = 500;

  constructor() {
    // Pre-allocate particle pool
    for (let i = 0; i < this.maxParticles; i++) {
      this.pool.push(new Particle());
    }
  }

  spawnExplosion(position: Vector3, color: Color, count: number) {
    const particlesToSpawn = Math.min(count, this.maxParticles - this.activeParticles.length);

    for (let i = 0; i < particlesToSpawn; i++) {
      const particle = this.pool.pop();
      if (!particle) continue;

      particle.position.copy(position);
      particle.velocity.set(
        (Math.random() - 0.5) * 150,
        (Math.random() - 0.5) * 150,
        (Math.random() - 0.5) * 100
      );
      particle.life = 1.5; // seconds
      particle.color.copy(color);
      particle.size = 2 + Math.random() * 4;

      this.activeParticles.push(particle);
    }
  }

  update(deltaTime: number) {
    for (let i = this.activeParticles.length - 1; i >= 0; i--) {
      const particle = this.activeParticles[i];
      particle.life -= deltaTime;

      if (particle.life <= 0) {
        this.pool.push(particle);
        this.activeParticles.splice(i, 1);
      }
    }

    // Enforce hard cap
    while (this.activeParticles.length > this.maxParticles) {
      const oldest = this.activeParticles.shift();
      if (oldest) this.pool.push(oldest);
    }
  }

  dispose() {
    for (const particle of this.pool) {
      particle.geometry?.dispose();
      particle.material?.dispose();
    }
    this.pool = [];
    this.activeParticles = [];
  }
}
