class ShockwaveRing {
  private ring: THREE.Mesh;
  private meshMaterial: THREE.MeshBasicMaterial;

  constructor() {
    const geometry = new THREE.RingGeometry(1, 1.2, 32);
    const material = new THREE.MeshBasicMaterial({
      color: 0x00ffff,
      transparent: true,
      opacity: 1,
      side: THREE.DoubleSide
    });

    this.ring = new THREE.Mesh(geometry, material);
    this.ring.position.y = 0.1;
    this.ring.rotation.x = -Math.PI / 2;

    // Dispose materials on cleanup
    this.ring.geometry.dispose({
      type: 'BufferGeometry',
      attribute: { value: null },
      index: { value: null }
    });
    this.ring.material?.dispose();
  }

  activate(position: Vector3) {
    this.ring.position.copy(position);
    this.ring.scale.set(1, 1, 1);
    this.ring.material.opacity = 1;

    // Animate in update loop
    this.ring.userData.scaleSpeed = 0.15;
    this.ring.userData.opacityDecay = 0.03;
  }

  update(deltaTime: number) {
    const scale = this.ring.scale.x;
    this.ring.scale.set(scale + this.ring.userData.scaleSpeed, 
                       this.ring.scale.y + this.ring.userData.scaleSpeed,
                       this.ring.scale.z + this.ring.userData.scaleSpeed);
    this.ring.material.opacity -= this.ring.userData.opacityDecay;

    if (this.ring.material.opacity <= 0) {
      return false; // Should be removed
    }

    return true;
  }
}
