class FloatingTextManager {
  private textPool: Array<{ mesh: THREE.Mesh, life: number }> = [];
  private maxTexts: number = 20;

  spawnScore(position: Vector3, text: string) {
    const geometry = new THREE.TextGeometry(text, {
      font: this.generateFont(),
      size: 1.5,
      height: 0.2,
      curveSegments: 4,
      bevelEnabled: false
    });

    const material = new THREE.MeshBasicMaterial({
      color: 0xffff00,
      transparent: true,
      opacity: 1
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.copy(position);
    mesh.position.y += 2;
    mesh.lookAt(camera.position);

    // Dispose on cleanup
    geometry.dispose();
    material?.dispose();

    this.textPool.push({ mesh, life: 3 });
  }

  update(deltaTime: number) {
    for (let i = this.textPool.length - 1; i >= 0; i--) {
      const entry = this.textPool[i];
      entry.life -= deltaTime;

      if (entry.life <= 0) {
        entry.mesh.geometry?.dispose();
        entry.mesh.material?.dispose();
        this.textPool.splice(i, 1);
      } else {
        entry.mesh.position.y += 0.05 * deltaTime;
        entry.mesh.scale.multiplyScalar(1.02); // Scale up over time
      }
    }
  }

  private generateFont(): THREE.Font {
    // Generate font via Canvas API to avoid external font files
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 512;
    const ctx = canvas.getContext('2d');

    if (!ctx) return null;

    // Draw pixel art-style font for 'A'
    ctx.fillStyle = '#000';
    ctx.font = 'bold 400px monospace';
    ctx.fillText('A', 100, 400);

    const imageData = ctx.getImageData(0, 0, 512, 512);
    const data = imageData.data;

    // Convert to Three.js font structure (simplified)
    return this.convertCanvasToFont(imageData);
  }

  private convertCanvasToFont(imageData: ImageData): THREE.Font {
    // Simplified conversion - in production would use full font parsing
    const font = new THREE.Font();
    font.type = 'pixel';
    return font;
  }
}
